function listenLocalServer(server) {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      server.off('error', reject);
      resolve(server.address());
    });
  });
}

function closeServer(server) {
  return new Promise((resolve, reject) => {
    server.close((error) => (error ? reject(error) : resolve()));
  });
}

async function makeTarStream(entries) {
  const pack = tarStream.pack();
  for (const entry of entries) {
    const data = Buffer.from(entry.text || '', 'utf8');
    await new Promise((resolve, reject) => {
      const header = {
        name: entry.name,
        type: entry.type || 'file',
        mode: entry.mode || 0o644,
        mtime: entry.mtime || new Date('2026-06-23T10:00:00.000Z')
      };
      if (entry.type === 'directory') {
        pack.entry(header, (error) => (error ? reject(error) : resolve()));
      } else {
        pack.entry(header, data, (error) => (error ? reject(error) : resolve()));
      }
    });
  }
  pack.finalize();
  return pack;
}

function readZipEntries(filePath) {
  return new Promise((resolve, reject) => {
    const entries = new Map();
    yauzl.open(filePath, { lazyEntries: true, autoClose: true }, (openError, zipfile) => {
      if (openError) {
        reject(openError);
        return;
      }
      zipfile.on('entry', (entry) => {
        const name = String(entry?.fileName || '');
        if (!name || name.endsWith('/')) {
          zipfile.readEntry();
          return;
        }
        zipfile.openReadStream(entry, (streamError, stream) => {
          if (streamError) {
            reject(streamError);
            return;
          }
          const chunks = [];
          stream.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
          stream.once('error', reject);
          stream.once('end', () => {
            entries.set(name, Buffer.concat(chunks));
            zipfile.readEntry();
          });
        });
      });
      zipfile.once('error', reject);
      zipfile.once('end', () => resolve(entries));
      zipfile.readEntry();
    });
  });
}

function collectTarEntries(stream) {
  return new Promise((resolve, reject) => {
    const entries = [];
    const extract = tarStream.extract();
    extract.on('entry', (header, entryStream, next) => {
      const chunks = [];
      entryStream.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
      entryStream.once('error', reject);
      entryStream.once('end', () => {
        entries.push({
          name: header.name,
          type: header.type,
          text: Buffer.concat(chunks).toString('utf8')
        });
        next();
      });
    });
    extract.once('error', reject);
    extract.once('finish', () => resolve(entries));
    stream.pipe(extract);
  });
}

test('UI readiness wait retries while a published port is still warming up', async () => {
  let hits = 0;
  const server = http.createServer((_req, res) => {
    res.on('error', () => {});
    hits += 1;
    if (hits === 1) {
      const timer = setTimeout(() => {
        if (!res.destroyed && !res.writableEnded) res.end('late');
      }, 180);
      if (typeof timer.unref === 'function') timer.unref();
      return;
    }
    res.statusCode = 200;
    res.end('ok');
  });
  const address = await listenLocalServer(server);

  try {
    const fakeDocker = {
      async inspectContainer(containerId) {
        assert.equal(containerId, 'container-1');
        return {
          NetworkSettings: {
            Ports: {
              '80/tcp': [{ HostPort: String(address.port) }]
            }
          }
        };
      }
    };

    const result = await waitForUiReachable(fakeDocker, 'container-1', {
      timeoutMs: 1500,
      intervalMs: 30,
      attemptTimeoutMs: 90
    });

    assert.equal(result.ok, true);
    assert.equal(result.uiUrl, `http://127.0.0.1:${address.port}/`);
    assert.ok(hits >= 2);
  } finally {
    await closeServer(server);
  }
});

test('local instance start readiness reports waiting until the UI responds', async () => {
  let hits = 0;
  const server = http.createServer((_req, res) => {
    hits += 1;
    if (hits < 3) {
      res.destroy();
      return;
    }
    res.statusCode = 200;
    res.end('ok');
  });
  const address = await listenLocalServer(server);
  const statusPatches = [];

  try {
    const fakeDocker = {
      async inspectContainer(containerId) {
        assert.equal(containerId, 'container-1');
        return {
          NetworkSettings: {
            Ports: {
              '80/tcp': [{ HostPort: String(address.port) }]
            }
          }
        };
      }
    };

    const result = await waitForStartedLocalInstanceUi(fakeDocker, 'container-1', {
      timeoutMs: 1500,
      intervalMs: 30,
      attemptTimeoutMs: 90,
      onStatus: (patch) => statusPatches.push(patch)
    });

    assert.equal(result.ok, true);
    assert.equal(result.uiUrl, `http://127.0.0.1:${address.port}/`);
    assert.deepEqual(statusPatches, [
      { message: 'Waiting for UI', uiReady: false },
      { message: 'UI ready', uiReady: true, uiUrl: `http://127.0.0.1:${address.port}/` }
    ]);
    assert.ok(hits >= 3);
  } finally {
    await closeServer(server);
  }
});

test('local instance start readiness can be aborted while the UI hangs', async () => {
  const server = http.createServer((_req, res) => {
    res.statusCode = 200;
    res.end('unused');
  });
  const address = await listenLocalServer(server);
  await closeServer(server);

  const controller = new AbortController();
  const statusPatches = [];
  const fakeDocker = {
    async inspectContainer(containerId) {
      assert.equal(containerId, 'container-1');
      return {
        NetworkSettings: {
          Ports: {
            '80/tcp': [{ HostPort: String(address.port) }]
          }
        }
      };
    }
  };

  const timer = setTimeout(() => controller.abort(), 50);
  if (typeof timer.unref === 'function') timer.unref();

  await assert.rejects(
    waitForStartedLocalInstanceUi(fakeDocker, 'container-1', {
      timeoutMs: 5000,
      intervalMs: 1000,
      attemptTimeoutMs: 90,
      signal: controller.signal,
      onStatus: (patch) => statusPatches.push(patch)
    }),
    (error) => error?.code === 'OP_CANCELED'
  );
  assert.deepEqual(statusPatches, [{ message: 'Waiting for UI', uiReady: false }]);
});

