{
  "name": "@a0-launcher/packaging",
  "private": true,
  "description": "Native desktop packaging toolchain for Agent Zero Launcher.",
  "dependencies": {
    "electron": "^42.5.1",
    "electron-builder": "^26.15.6"
  }
}

const path = require("node:path");

const LAUNCHER_UPDATER_LOG_RELATIVE_PATH = path.join("logs", "launcher-updater.log");

function resolveLauncherUpdaterLogPath(options = {}) {
  const userDataPath = String(options.userDataPath || "").trim();
  if (!userDataPath) {
    return "";
  }

  const platform = String(options.platform || "").trim();
  const pathModule = platform === "win32" || /\\/u.test(userDataPath) ? path.win32 : path;

  return pathModule.join(userDataPath, LAUNCHER_UPDATER_LOG_RELATIVE_PATH);
}

function resolveWindowsUpdaterInstallerArgs(options = {}) {
  const args = ["--updated"];
  const isSilent = options.isSilent === true;
  const shouldForceRunAfter = isSilent
    ? options.isForceRunAfter === true
    : options.autoRunAppAfterInstall !== false;
  const packagePath = String(options.packagePath || "").trim();

  if (isSilent) {
    args.push("/S");
  }

  if (shouldForceRunAfter) {
    args.push("--force-run");
  }

  if (packagePath) {
    args.push(`--package-file=${packagePath}`);
  }

  return args;
}

module.exports = {
  LAUNCHER_UPDATER_LOG_RELATIVE_PATH,
  resolveLauncherUpdaterLogPath,
  resolveWindowsUpdaterInstallerArgs
};

const childProcess = require('node:child_process');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const semver = require('semver');

const A0_CLI_INSTALL_SCRIPT_URL = 'https://raw.githubusercontent.com/agent0ai/a0-connector/main/install.sh';
const A0_CLI_INSTALL_SCRIPT_URL_WINDOWS = 'https://raw.githubusercontent.com/agent0ai/a0-connector/main/install.ps1';
const A0_CLI_RELEASE_API_URL = 'https://api.github.com/repos/agent0ai/a0-connector/releases/latest';

function normalizeA0CliVersion(value) {
  const match = String(value || '').match(/\bv?(\d+\.\d+(?:\.\d+)?)\b/i);
  return semver.coerce(match?.[1] || '')?.version || '';
}

function shouldInstallA0Cli({ installed = false, supportsGateway = false, currentVersion = '', latestVersion = '' } = {}) {
  if (!installed || !supportsGateway) return true;
  const current = normalizeA0CliVersion(currentVersion);
  const latest = normalizeA0CliVersion(latestVersion);
  return !!latest && (!current || semver.gt(latest, current));
}

function a0CliInstallCommand(platform = process.platform, scriptPath = '') {
  if (platform === 'win32') {
    if (!scriptPath) throw new Error('A downloaded A0 CLI installer is required.');
    return {
      command: 'powershell.exe',
      args: [
        '-NoLogo',
        '-NoProfile',
        '-ExecutionPolicy',
        'RemoteSigned',
        '-NonInteractive',
        '-File',
        scriptPath
      ]
    };
  }
  if (platform === 'darwin' || platform === 'linux') {
    const script = [
      'tmp="$(mktemp "${TMPDIR:-/tmp}/a0-cli-install.XXXXXX")" || exit 1',
      'trap \'rm -f "$tmp"\' EXIT INT TERM',
      `if command -v curl >/dev/null 2>&1; then curl -LsSf '${A0_CLI_INSTALL_SCRIPT_URL}' -o "$tmp"`,
      `elif command -v wget >/dev/null 2>&1; then wget -qO "$tmp" '${A0_CLI_INSTALL_SCRIPT_URL}'`,
      'else echo "curl or wget is required to install A0 CLI." >&2; exit 127; fi',
      'sh "$tmp"'
    ].join('; ');
    return { command: 'sh', args: ['-c', script] };
  }
  const error = new Error('Installing A0 CLI is not available on this system.');
  error.code = 'TERMINAL_UNAVAILABLE';
  throw error;
}

async function runA0CliInstaller({ platform = process.platform, spawn = childProcess.spawn, env = process.env, fetch = globalThis.fetch } = {}) {
  let tempDir;
  try {
    let scriptPath = '';
    if (platform === 'win32') {
      const response = await fetch(A0_CLI_INSTALL_SCRIPT_URL_WINDOWS, { signal: AbortSignal.timeout(30000) });
      if (!response.ok) throw new Error(`A0 CLI installer download failed (HTTP ${response.status}).`);
      const script = await response.text();
      tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'a0-cli-install-'));
      scriptPath = path.join(tempDir, 'install.ps1');
      await fs.writeFile(scriptPath, script, { encoding: 'utf8', flag: 'wx' });
    }
    const spec = a0CliInstallCommand(platform, scriptPath);
    return await runInstallerCommand(spec, { spawn, env });
  } finally {
    if (tempDir) await fs.rm(tempDir, { recursive: true, force: true });
  }
}

function runInstallerCommand(spec, { spawn, env }) {
  return new Promise((resolve, reject) => {
    let settled = false;
    const finish = (error) => {
      if (settled) return;
      settled = true;
      if (error) reject(error);
      else resolve({ installed: true });
    };

    let child;
    try {
      child = spawn(spec.command, spec.args, {
        stdio: 'ignore',
        windowsHide: true,
        env
      });
    } catch (error) {
      finish(error);
      return;
    }

    child.once('error', finish);
    child.once('exit', (code, signal) => {
      if (code === 0) {
        finish();
        return;
      }
      const error = new Error(`A0 CLI installer exited (${code ?? signal ?? 'unknown'}).`);
      error.code = 'CLI_INSTALL_FAILED';
      finish(error);
    });
  });
}

function runA0CliUpdate(cli, { spawn = childProcess.spawn, env = process.env } = {}) {
  const binary = String(cli || '').trim();
  if (!binary) {
    const error = new Error('A0 CLI was not found.');
    error.code = 'TERMINAL_UNAVAILABLE';
    return Promise.reject(error);
  }

  return new Promise((resolve, reject) => {
    let output = '';
    let child;
    try {
      child = spawn(binary, ['update'], {
        stdio: ['ignore', 'pipe', 'pipe'],
        windowsHide: true,
        env
      });
    } catch (error) {
      reject(error);
      return;
    }

    child.once('error', reject);
    child.stdout.on('data', (chunk) => { output = (output + chunk.toString()).slice(-8192); });
    child.stderr.resume();
    // The CLI exits before its updater. Inherited pipes close after the handoff finishes.
    child.once('close', (code, signal) => {
      if (code === 0 && /(?:^|\r?\n)Update complete\. Run a0\.(?:\r?\n|$)/.test(output)) {
        resolve({ updated: true });
        return;
      }
      const error = new Error(`A0 CLI update did not complete (${code ?? signal ?? 'unknown'}).`);
      error.code = 'CLI_UPDATE_FAILED';
      reject(error);
    });
  });
}

module.exports = {
  A0_CLI_RELEASE_API_URL,
  a0CliInstallCommand,
  normalizeA0CliVersion,
  runA0CliInstaller,
  runA0CliUpdate,
  shouldInstallA0Cli
};

function macAccessibilityPermissionMessage({ isPackaged = true } = {}) {
  return isPackaged
    ? 'Allow Agent Zero Launcher in macOS Accessibility settings.'
    : 'Allow Electron (this Launcher dev build) in macOS Accessibility settings.';
}

function macScreenRecordingPermissionMessage({ isPackaged = true } = {}) {
  return isPackaged
    ? 'Allow Agent Zero Launcher in macOS Screen Recording settings.'
    : 'Allow Electron (this Launcher dev build) in macOS Screen Recording settings.';
}

function macMicrophonePermissionMessage({ isPackaged = true } = {}) {
  return isPackaged
    ? 'Allow Agent Zero Launcher in macOS Microphone settings, then restart Launcher.'
    : 'Allow Electron (this Launcher dev build) in macOS Microphone settings, then restart Launcher.';
}

function localizeMacPermissionStatus(status = {}, { isPackaged = true } = {}) {
  const setup = status?.gateway?.status?.computer_use?.setup;
  const state = String(setup?.state || '').trim().toLowerCase();
  const message = state === 'accessibility_required'
    ? macAccessibilityPermissionMessage({ isPackaged })
    : state === 'screen_recording_required'
      ? macScreenRecordingPermissionMessage({ isPackaged })
      : '';
  if (!message) return status;
  return {
    ...status,
    gateway: {
      ...status.gateway,
      status: {
        ...status.gateway.status,
        computer_use: {
          ...status.gateway.status.computer_use,
          setup: {
            ...setup,
            message
          }
        }
      }
    }
  };
}

async function ensureMacAccessibilityPermission(systemPreferences, {
  prompt = false,
  timeoutMs = 120000,
  pollIntervalMs = 500,
  wait = (delay) => new Promise((resolve) => setTimeout(resolve, delay)),
  onPrompt = () => {}
} = {}) {
  const trusted = (shouldPrompt) => {
    try {
      return systemPreferences?.isTrustedAccessibilityClient?.(shouldPrompt) === true;
    } catch {
      return false;
    }
  };
  if (trusted(false)) return { granted: true, prompted: false };
  if (!prompt) return { granted: false, prompted: false };

  onPrompt();
  if (trusted(true)) return { granted: true, prompted: true };
  const deadline = Date.now() + Math.max(0, Number(timeoutMs) || 0);
  while (Date.now() < deadline) {
    await wait(Math.max(10, Number(pollIntervalMs) || 500));
    if (trusted(false)) return { granted: true, prompted: true };
  }
  return { granted: false, prompted: true };
}

async function ensureMacMicrophonePermission(systemPreferences, { prompt = false } = {}) {
  const status = () => {
    try {
      return String(systemPreferences?.getMediaAccessStatus?.('microphone') || 'unknown');
    } catch {
      return 'unknown';
    }
  };
  const initial = status();
  if (initial === 'granted') return { granted: true, prompted: false };
  if (!prompt || initial !== 'not-determined') return { granted: false, prompted: false };
  try {
    const granted = await systemPreferences?.askForMediaAccess?.('microphone');
    return { granted: granted === true || status() === 'granted', prompted: true };
  } catch {
    return { granted: false, prompted: true };
  }
}

module.exports = {
  ensureMacAccessibilityPermission,
  ensureMacMicrophonePermission,
  localizeMacPermissionStatus,
  macAccessibilityPermissionMessage,
  macMicrophonePermissionMessage,
  macScreenRecordingPermissionMessage
};

import {
  ADVANCED_INSTANCE_MODEL_SLOTS,
  PRIMARY_INSTANCE_MODEL_SLOTS,
  bindInstanceDefaultDirtyTracking,
  buildInstanceEnvText,
  defaultInstanceName,
  normalizeInstanceDefaults,
  providerApiKeyPlaceholder,
  readInstanceDefaultsFromForm
} from "../instance-defaults.js";
import { shouldShowSetupShowcase } from "../setup-showcase/setup-showcase.js";
import { asText } from "../component-utils.js";

const FIRST_INSTANCE_SETUP_CLASS = "dm-first-instance-setup";
const FIRST_INSTANCE_SETUP_PREFIX = "firstSetup";
const STEP_MODELS = "models";
const STEP_FIRST_INSTANCE = "first-instance";
const STORAGE_MODE_HOST_DIRECTORY = "host_directory";
const STORAGE_MODE_NAMED_VOLUME = "named_volume";
const STORAGE_MODE_EPHEMERAL = "ephemeral";

const acknowledgedOps = new Set();

function createEl(tagName, className = "", text = "") {
  const el = document.createElement(tagName);
  if (className) el.className = className;
  if (text) el.textContent = text;
  return el;
}

function slotFieldId(slotId, field) {
  return `${FIRST_INSTANCE_SETUP_PREFIX}${slotId}${field}`;
}

function createProviderSelect(slot, value) {
  const select = createEl("select", "dm-select");
  select.id = slotFieldId(slot.id, "Provider");
  select.setAttribute("aria-label", `${slot.label} provider`);
  for (const [optionValue, label] of slot.providerOptions || []) {
    const option = createEl("option", "", label);
    option.value = optionValue;
    if (optionValue === value) option.selected = true;
    select.appendChild(option);
  }
  select.value = value || slot.defaultProvider;
  return select;
}

function createModelRows(slots, defaults) {
  const grid = createEl("div", "dm-model-grid");
  const normalized = normalizeInstanceDefaults(defaults);
  for (const slot of slots) {
    const entry = normalized.models[slot.id] || {};
    const section = createEl("div", "dm-model-section");
    section.appendChild(createEl("div", "dm-model-label", slot.label));

    const controls = createEl("div", "dm-model-controls");
    const row = createEl("div", "dm-model-row");
    row.appendChild(createProviderSelect(slot, entry.provider || slot.defaultProvider));

    const model = createEl("input", "dm-text-input");
    model.id = slotFieldId(slot.id, "Model");
    model.type = "text";
    model.autocomplete = "off";
    model.value = entry.model || "";
    model.placeholder = slot.modelPlaceholder || "";
    model.setAttribute("aria-label", `${slot.label} model`);
    row.appendChild(model);

    controls.appendChild(row);

    const apiKey = createEl("input", "dm-text-input dm-model-api-key");
    apiKey.id = slotFieldId(slot.id, "ApiKey");
    apiKey.type = "password";
    apiKey.autocomplete = "off";
    apiKey.value = entry.apiKey || "";
    apiKey.placeholder = providerApiKeyPlaceholder(slot, entry.provider || slot.defaultProvider);
    apiKey.setAttribute("aria-label", `${slot.label} API key`);
    controls.appendChild(apiKey);

    section.appendChild(controls);
    grid.appendChild(section);
  }
  return grid;
}

function initialStorageMode(state = {}) {
  const mode = asText(state?.storagePreferences?.mode);
  return mode === STORAGE_MODE_NAMED_VOLUME ? STORAGE_MODE_NAMED_VOLUME : STORAGE_MODE_HOST_DIRECTORY;
}

function syncStorageWarning(section) {
  const warning = section?.querySelector?.(".dm-first-instance-storage-warning");
  const select = section?.querySelector?.("#firstSetupStorageMode");
  if (warning) warning.classList.toggle("hidden", select?.value !== STORAGE_MODE_EPHEMERAL);
}

function hasLocalInstance(state = {}) {
  return Array.isArray(state?.containers) && state.containers.some((container) =>
    asText(container?.containerId) || asText(container?.containerName)
  );
}

function installIsComplete(progress = null) {
  return asText(progress?.type) === "install" && asText(progress?.status) === "completed";
}

function shouldOfferFirstInstanceSetup(progress = null) {
  if (asText(progress?.type) !== "install") return false;
  if (installIsComplete(progress)) return true;
  return shouldShowSetupShowcase(progress);
}

function shouldShowFirstInstanceSetup(state = {}) {
  return false;
}

function setStep(panel, step) {
  const nextStep = step === STEP_FIRST_INSTANCE ? STEP_FIRST_INSTANCE : STEP_MODELS;
  panel.dataset.step = nextStep;

  const modelsStep = panel.querySelector(".dm-first-instance-step-models");
  const runStep = panel.querySelector(".dm-first-instance-step-run");
  if (modelsStep) modelsStep.classList.toggle("hidden", nextStep !== STEP_MODELS);
  if (runStep) runStep.classList.toggle("hidden", nextStep !== STEP_FIRST_INSTANCE);

  const title = panel.querySelector(".dm-first-instance-title");
  if (title) title.textContent = nextStep === STEP_FIRST_INSTANCE ? "Start your first Instance" : "Choose Instance defaults";

  const description = panel.querySelector(".dm-first-instance-description");
  if (description) {
    description.textContent = nextStep === STEP_FIRST_INSTANCE
      ? "Use the defaults you just chose for the first Instance, or save them for later."
      : "Choose the providers and models Agent Zero should use for new Instances.";
  }

  const back = panel.querySelector(".dm-first-instance-back");
  if (back) {
    back.classList.toggle("hidden", nextStep === STEP_MODELS);
    back.textContent = "< Back to model configuration";
  }
}

function createRunChoice(state) {
  const progress = state?.progress || null;
  const runBlock = createEl("div", "dm-first-instance-run");

  const field = createEl("div", "dm-field dm-first-instance-name-field");
  const fieldLabel = createEl("label", "", "Instance name");
  fieldLabel.setAttribute("for", "firstSetupInstanceName");
  field.appendChild(fieldLabel);
  const nameInput = createEl("input", "dm-text-input");
  nameInput.id = "firstSetupInstanceName";
  nameInput.type = "text";
  nameInput.maxLength = 64;
  nameInput.autocomplete = "off";
  nameInput.value = defaultInstanceName(asText(progress?.targetTag) || "latest", state);
  field.appendChild(nameInput);
  field.appendChild(createEl("div", "dm-field-hint", "The name is only for the first Instance. Model defaults stay reusable."));
  runBlock.appendChild(field);

  const storageField = createEl("div", "dm-field dm-first-instance-storage-field");
  const storageLabel = createEl("label", "", "Workspace storage");
  storageLabel.setAttribute("for", "firstSetupStorageMode");
  storageField.appendChild(storageLabel);
  const storageSelect = createEl("select", "dm-select");
  storageSelect.id = "firstSetupStorageMode";
  const storageOptions = [
    [STORAGE_MODE_HOST_DIRECTORY, "Persistent workspace (recommended)"],
    [STORAGE_MODE_NAMED_VOLUME, "Named Docker volume"],
    [STORAGE_MODE_EPHEMERAL, "No persistent workspace"]
  ];
  for (const [value, labelText] of storageOptions) {
    const option = createEl("option", "", labelText);
    option.value = value;
    storageSelect.appendChild(option);
  }
  storageSelect.value = initialStorageMode(state);
  storageSelect.addEventListener("change", () => syncStorageWarning(runBlock));
  storageField.appendChild(storageSelect);
  storageField.appendChild(createEl("div", "dm-field-hint", "Persistent choices mount a separate workspace at /a0/usr."));
  const storageWarning = createEl(
    "div",
    "dm-field-hint dm-first-instance-storage-warning hidden",
    "No volume makes this Instance ephemeral: files and settings live inside the container and can be lost if it is replaced or deleted. You can persist it later from the Instance menu; the old container is kept until the replacement starts."
  );
  storageField.appendChild(storageWarning);
  runBlock.appendChild(storageField);
  syncStorageWarning(runBlock);

  const label = createEl("label", "dm-checkbox-line dm-first-instance-check");
  const checkbox = document.createElement("input");
  checkbox.id = "firstSetupRunInstance";
  checkbox.type = "checkbox";
  label.appendChild(checkbox);
  label.appendChild(createEl(
    "span",
    "",
    installIsComplete(progress)
      ? "Start my first Instance after I finish these choices"
      : "Start my first Instance when the download finishes"
  ));
  runBlock.appendChild(label);

  return runBlock;
}

function finishSetup(progress, actions, onDone) {
  const opId = asText(progress?.opId);
  if (opId) acknowledgedOps.add(opId);
  const finished = actions?.finishFirstInstanceSetup?.({ opId, targetTag: asText(progress?.targetTag) });
  const complete = (ok) => {
    if (ok === false) return false;
    onDone?.();
    return true;
  };
  if (finished && typeof finished.then === "function") return finished.then(complete);
  return complete(finished);
}

function syncFirstInstanceSetupState(panel, state = {}) {
  if (!panel) return;
  const progress = state?.progress || null;
  const checkLabel = panel.querySelector(".dm-first-instance-check")?.querySelector("span");
  if (checkLabel) {
    checkLabel.textContent = installIsComplete(progress)
      ? "Start my first Instance after I finish these choices"
      : "Start my first Instance when the download finishes";
  }
  setStep(panel, panel.dataset.step || STEP_MODELS);
}

function createFirstInstanceSetup(state, actions, onDone) {
  const progress = state?.progress || null;
  const instanceDefaults = normalizeInstanceDefaults(state?.instanceDefaults);
  const section = createEl("section", FIRST_INSTANCE_SETUP_CLASS);
  section.setAttribute("aria-label", "Choose Instance defaults");

  const head = createEl("div", "dm-first-instance-head");
  head.appendChild(createEl("h3", "dm-first-instance-title", "Choose Instance defaults"));
  head.appendChild(createEl("p", "dm-first-instance-description", "Choose the providers and models Agent Zero should use for new Instances."));
  section.appendChild(head);

  const layout = createEl("div", "dm-first-instance-layout");

  const modelsPane = createEl("div", "dm-first-instance-step dm-first-instance-step-models");
  const primaryField = createEl("div", "dm-field dm-model-defaults");
  primaryField.appendChild(createEl("div", "dm-field-label", "Main and Utility"));
  primaryField.appendChild(createModelRows(PRIMARY_INSTANCE_MODEL_SLOTS, instanceDefaults));
  primaryField.appendChild(createEl("div", "dm-field-hint", "Using a subscription provider? Leave keys empty and connect it during Agent Zero onboarding."));
  modelsPane.appendChild(primaryField);

  const advanced = createEl("details", "dm-advanced dm-first-instance-advanced");
  const summary = createEl("summary", "", "Advanced");
  advanced.appendChild(summary);
  const advancedBody = createEl("div", "dm-advanced-body");
  const advancedField = createEl("div", "dm-field dm-model-defaults");
  advancedField.appendChild(createEl("div", "dm-field-label", "Embedding model"));
  advancedField.appendChild(createModelRows(ADVANCED_INSTANCE_MODEL_SLOTS, instanceDefaults));
  advancedBody.appendChild(advancedField);
  advanced.appendChild(advancedBody);
  modelsPane.appendChild(advanced);
  layout.appendChild(modelsPane);

  const runPane = createEl("div", "dm-first-instance-step dm-first-instance-step-run hidden");
  runPane.appendChild(createRunChoice(state));
  layout.appendChild(runPane);

  section.appendChild(layout);

  const actionRow = createEl("div", "dm-first-instance-actions");
  const back = createEl("button", "dm-text-button dm-first-instance-back hidden", "< Back to model configuration");
  back.type = "button";
  back.addEventListener("click", () => setStep(section, STEP_MODELS));
  actionRow.appendChild(back);

  const skip = createEl("button", "dm-text-button dm-first-instance-skip", "Skip");
  skip.type = "button";
  skip.addEventListener("click", async () => {
    const ok = await actions?.skipFirstInstanceSetup?.({ opId: asText(progress?.opId) });
    if (ok === false) return;
    await finishSetup(progress, actions, onDone);
  });
  actionRow.appendChild(skip);

  const primary = createEl("button", "button confirm dm-first-instance-primary", "Continue");
  primary.type = "button";
  primary.addEventListener("click", async () => {
    const defaults = readInstanceDefaultsFromForm(section, FIRST_INSTANCE_SETUP_PREFIX);
    const envResult = buildInstanceEnvText(defaults);
    if (!envResult.ok) {
      window.toastFrontendError?.(envResult.message, "Agent Zero");
      return;
    }

    if (section.dataset.step !== STEP_FIRST_INSTANCE) {
      setStep(section, STEP_FIRST_INSTANCE);
      return;
    }

    const ok = await actions?.confirmFirstInstanceSetup?.({
      opId: asText(progress?.opId),
      targetTag: asText(progress?.targetTag),
      instanceDefaults: defaults,
      runFirstInstance: section.querySelector("#firstSetupRunInstance")?.checked === true,
      instanceName: section.querySelector("#firstSetupInstanceName")?.value || "",
      storageMode: section.querySelector("#firstSetupStorageMode")?.value || ""
    });
    if (!ok) return;
    await finishSetup(progress, actions, onDone);
  });
  actionRow.appendChild(primary);
  section.appendChild(actionRow);

  bindInstanceDefaultDirtyTracking(section, FIRST_INSTANCE_SETUP_PREFIX);
  setStep(section, STEP_MODELS);
  return section;
}

function mountFirstInstanceSetup(parent, state = {}, actions = {}, onDone = null) {
  if (!parent) return null;
  let panel = parent.querySelector(`.${FIRST_INSTANCE_SETUP_CLASS}`);
  if (!panel) {
    panel = createFirstInstanceSetup(state, actions, onDone);
    parent.appendChild(panel);
  } else {
