});

// An absent field must stay absent: the shell applies every field it receives,
// so an empty name or URL would overwrite the saved one.
test('updateRemoteInstance forwards only the fields it was given', async () => {
  const api = exposed.dockerManagerAPI;
  invocations.length = 0;
  await api.updateRemoteInstance('remote_1', { allowUntrustedCertificate: true });
  await api.updateRemoteInstance('remote_1', {
    name: 'Lab',
    url: 'https://a0.example.com/',
    allowUntrustedCertificate: false
  });
  await api.updateRemoteInstance('remote_1', { name: 42, url: null, allowUntrustedCertificate: 'yes' });

  assert.ok(invocations.every(({ channel }) => channel === 'docker-manager:updateRemoteInstance'));
  assert.deepEqual(invocations.map(({ body }) => body), [
    { id: 'remote_1', allowUntrustedCertificate: true },
    { id: 'remote_1', name: 'Lab', url: 'https://a0.example.com/', allowUntrustedCertificate: false },
    { id: 'remote_1' }
  ]);
});

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const mainSource = fs.readFileSync(path.join(__dirname, 'main.js'), 'utf8');
const loadingSource = fs.readFileSync(path.join(__dirname, 'loading.html'), 'utf8');
const rendererSource = fs.readFileSync(path.join(__dirname, '..', 'app', 'docker_manager.js'), 'utf8');

test('startup keeps splash timing bounded and remote freshness off the critical path', () => {
  const entryMs = Number(mainSource.match(/SPLASH_ENTRY_ANIMATION_MS = (\d+)/)?.[1]);
  const exitMs = Number(mainSource.match(/SPLASH_EXIT_ANIMATION_MS = (\d+)/)?.[1]);
  assert.equal(loadingSource.includes(`splash-open ${entryMs}ms`), true);
  assert.equal(loadingSource.includes(`splash-close ${exitMs}ms`), true);
  assert.ok(entryMs + exitMs <= 750);

  const lifecycle = mainSource.slice(mainSource.indexOf('app.whenReady()'), mainSource.indexOf("app.on('window-all-closed'"));
  assert.doesNotMatch(lifecycle, /setTimeout|delayMs/);
  assert.match(lifecycle, /await createWindow\(\)/);
  assert.match(rendererSource, /await refresh\(\{ forceRefresh: false \}\)/);
  assert.match(rendererSource, /!Number\.isFinite\(initialSyncMs\) \|\| initialSyncMs < refreshStartedAt/);
  assert.match(rendererSource, /dockerManagerAPI\?\.refresh\?\.\(\{ forceRefresh: true \}\)/);
});

test('available launcher update shows actions without redundant status copy', () => {
  assert.match(loadingSource, /statusEl\.hidden = state === 'update-available'/);
  assert.match(loadingSource, /body\.requires-action \.status:not\(\[hidden\]\)/);
  assert.equal(loadingSource.match(/statusEl\.hidden = false/g)?.length, 2);
});
